<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Bell, CopyDocument, Key, Medal, Plus, Refresh, Setting } from '@element-plus/icons-vue'
import { errorMessage } from '../../api'
import ConfirmDialog from '../../components/ConfirmDialog.vue'
import FeedbackBanner from '../../components/FeedbackBanner.vue'
import EmptyState from '../../components/EmptyState.vue'
import PageHeader from '../../components/PageHeader.vue'
import StatusTag from '../../components/StatusTag.vue'
import { platformStore } from '../../stores/platform'
import { licenseStatus, type ApiSchool } from '../../stores/platformApiModel'
import { makeFeedback, type FeedbackState } from '../../stores/feedbackModel'
import { operationSuccess, type OperationKind } from '../../stores/interactionModel'

const route = useRoute(); const router = useRouter(); const surface = computed(() => String(route.meta.surface ?? 'home')); const error = ref(''); const busy = ref(false); const feedback = ref<FeedbackState | null>(null)
const confirmState = ref<{ title: string; description: string; confirmText: string; danger: boolean; work: () => Promise<unknown>; success: OperationKind } | null>(null)
const schoolOpen = ref(false); const competitionOpen = ref(false); const announcementOpen = ref(false)
const schoolForm = reactive({ name: '', license_expires_at: '2027-07-31', is_active: true })
const competitionForm = reactive({ title: '', registration_deadline: '2026-12-31', description: '' })
const announcementForm = reactive({ title: '', body: '' })
const school = computed(() => platformStore.state.schools.find((item) => item.id === Number(route.params.id)))
const headings = computed<Record<string, [string, string, string]>>(() => ({ home: ['平台运营', '全局授权与内容治理概览', '只管理学校空间、授权和全局内容，不进入校内项目材料。'], schools: ['学校空间', '学校与邀请码', '创建学校空间、查看配额与基础使用。'], school: ['学校空间', school.value?.name ?? '学校详情', '授权、邀请码、配额和基础使用概览。'], competitions: ['全局内容', '赛事管理', '创建、发布与撤回面向全平台的赛事信息。'], announcements: ['全局内容', '系统公告', '发布面向全平台师生的系统公告。'], cases: ['内容治理', '公开案例治理', '案例公开流程接入后在此集中治理。'], settings: ['平台配置', '安全与服务策略', '平台安全边界、配额和部署配置。'] }))
const heading = computed(() => headings.value[surface.value] ?? headings.value.home)
const valid = computed(() => platformStore.state.schools.filter((item) => item.is_authorized).length)
const expiring = computed(() => platformStore.state.schools.filter((item) => licenseStatus(item) === 'expiring').length)
onMounted(() => { platformStore.load().catch((reason) => { error.value = errorMessage(reason) }) })
async function action(work: () => Promise<unknown>, success?: OperationKind) { error.value = ''; busy.value = true; feedback.value = null; try { await work(); if (success) feedback.value = makeFeedback('success', operationSuccess(success)) } catch (reason) { feedback.value = makeFeedback('error', errorMessage(reason), '状态没有改变，可以重试。', '重试') } finally { busy.value = false } }
function askConfirm(config: NonNullable<typeof confirmState.value>) { confirmState.value = config }
async function confirmAction() { if (!confirmState.value) return; const current = confirmState.value; confirmState.value = null; await action(current.work, current.success) }
async function addSchool() { if (!schoolForm.name.trim()) { feedback.value = makeFeedback('error', '请输入学校名称', '学校名称不能为空。'); return } await action(() => platformStore.createSchool({ ...schoolForm })); if (!feedback.value?.tone || feedback.value.tone === 'success') { schoolOpen.value = false; schoolForm.name = '' } }
async function addCompetition() { if (!competitionForm.title.trim()) { feedback.value = makeFeedback('error', '请输入赛事名称', '赛事名称不能为空。'); return } await action(() => platformStore.createCompetition({ ...competitionForm, status: 'draft', audience: 'all' })); if (!feedback.value?.tone || feedback.value.tone === 'success') { competitionOpen.value = false; competitionForm.title = ''; competitionForm.description = '' } }
async function addAnnouncement() { if (!announcementForm.title.trim() || !announcementForm.body.trim()) { feedback.value = makeFeedback('error', '请填写公告标题和正文', '标题和正文都不能为空。'); return } await action(() => platformStore.announce(announcementForm.title, announcementForm.body)); if (!feedback.value?.tone || feedback.value.tone === 'success') { announcementOpen.value = false; Object.assign(announcementForm, { title: '', body: '' }) } }
async function copyInvite(code: string) { try { await window.navigator.clipboard?.writeText(code); feedback.value = makeFeedback('success', '邀请码已复制到剪贴板。', '请通过安全渠道发送给学校管理员。') } catch { feedback.value = makeFeedback('error', '浏览器未允许复制', '请手动选择邀请码。') } }
function toggleSchool(item: ApiSchool) { askConfirm({ title: item.is_active ? '停用学校授权？' : '恢复学校授权？', description: item.is_active ? '停用后师生只能读取历史数据，不能创建、提交或审核。' : '恢复后师生可以继续进行项目操作。', confirmText: item.is_active ? '停用并只读' : '恢复授权', danger: item.is_active, work: () => platformStore.updateSchool(item.id, { is_active: !item.is_active }), success: item.is_active ? 'school_disabled' : 'school_enabled' }) }
</script>
<template><div class="page platform-page"><PageHeader :eyebrow="heading[0]" :title="heading[1]" :description="heading[2]"><template #actions><button v-if="surface === 'schools'" class="primary-button" type="button" @click="schoolOpen = true"><el-icon><Plus /></el-icon> 创建学校</button><button v-if="surface === 'competitions'" class="primary-button" type="button" @click="competitionOpen = true"><el-icon><Plus /></el-icon> 创建赛事</button><button v-if="surface === 'announcements'" class="primary-button" type="button" @click="announcementOpen = true"><el-icon><Plus /></el-icon> 发布系统公告</button></template></PageHeader><FeedbackBanner v-model="feedback" @action="platformStore.load().catch((reason) => { feedback = makeFeedback('error', errorMessage(reason)) })" /><p v-if="error" class="form-error" role="alert">{{ error }}</p><template v-if="surface === 'home'"><div class="metric-grid platform-metrics"><RouterLink to="/platform/schools" class="metric-card"><small>学校空间</small><strong>{{ platformStore.state.schools.length }}</strong><span>覆盖 {{ platformStore.state.schools.reduce((sum, item) => sum + item.student_count + item.teacher_count, 0) }} 位师生</span></RouterLink><RouterLink to="/platform/schools" class="metric-card success"><small>有效授权</small><strong>{{ valid }}</strong><span>当前可正常写入</span></RouterLink><RouterLink to="/platform/schools" class="metric-card risk"><small>到期风险</small><strong>{{ expiring }}</strong><span>90 天内到期</span></RouterLink><RouterLink to="/platform/competitions" class="metric-card"><small>已发布赛事</small><strong>{{ platformStore.state.competitions.filter((item) => item.status === 'published').length }}</strong><span>全平台内容</span></RouterLink></div><div class="console-grid"><section class="console-panel"><div class="section-heading"><div><p class="eyebrow">授权健康</p><h2>学校状态</h2></div><RouterLink to="/platform/schools">管理学校 →</RouterLink></div><div v-for="item in platformStore.state.schools" :key="item.id" class="license-health"><span class="school-monogram">{{ item.name.slice(0, 1) }}</span><div><strong>{{ item.name }}</strong><small>到期 {{ item.license_expires_at ?? '长期' }}</small></div><StatusTag :status="item.is_authorized ? 'active' : 'disabled'" /></div></section><section class="console-panel"><p class="eyebrow">内容概览</p><h2>正在服务全平台</h2><div class="content-metric"><el-icon><Medal /></el-icon><span><strong>{{ platformStore.state.competitions.filter((item) => item.status === 'published').length }} 项赛事</strong><small>{{ platformStore.state.competitions.filter((item) => item.status === 'draft').length }} 个草稿</small></span></div><div class="content-metric"><el-icon><Bell /></el-icon><span><strong>{{ platformStore.state.announcements.length }} 条系统公告</strong><small>平台统一发布</small></span></div></section></div></template><template v-else-if="surface === 'schools'"><section class="data-table"><header><span>学校空间</span><span>邀请码</span><span>师生 / 项目</span><span>授权到期</span><span>启停</span><span>状态</span></header><div v-for="item in platformStore.state.schools" :key="item.id" class="data-row" role="link" tabindex="0" :aria-label="`查看 ${item.name} 详情`" @click="router.push(`/platform/schools/${item.id}`)" @keydown.enter="router.push(`/platform/schools/${item.id}`)"><div class="school-cell"><span class="school-monogram">{{ item.name.slice(0, 1) }}</span><strong>{{ item.name }}</strong></div><code>{{ item.invite_code }}</code><span>{{ item.student_count + item.teacher_count }} / {{ item.project_count }}</span><span>{{ item.license_expires_at ?? '长期' }}</span><el-switch :model-value="item.is_active" :disabled="busy" size="small" @change="toggleSchool(item)" @click.stop /><StatusTag :status="item.is_authorized ? 'active' : 'disabled'" /></div></section></template><template v-else-if="surface === 'school' && school"><div class="school-detail-grid"><section class="paper-card school-license-card"><div class="section-heading"><div><p class="eyebrow">学校邀请码</p><h2>{{ school.invite_code }}</h2></div><button class="icon-button" type="button" aria-label="复制学校邀请码" @click="copyInvite(school.invite_code)"><el-icon><CopyDocument /></el-icon></button></div><p>学生与教师注册时通过此邀请码绑定学校空间。</p><button class="secondary-button" :disabled="busy" type="button" @click="askConfirm({ title: '重置学校邀请码？', description: '旧邀请码会立即失效，已经拿到旧邀请码但尚未注册的用户需要重新获取。', confirmText: '确认重置', danger: true, work: () => platformStore.resetInvite(school!.id), success: 'invite_reset' })"><el-icon><Refresh /></el-icon> 重置邀请码</button></section><section class="school-license-card"><p class="eyebrow">授权状态</p><StatusTag :status="school.is_authorized ? 'active' : 'disabled'" /><h2>{{ school.is_authorized ? '学校当前可正常使用' : '学校当前为历史只读' }}</h2><p>授权到期：{{ school.license_expires_at ?? '长期' }}</p><button :class="school.is_active ? 'return-button' : 'approve-button'" :disabled="busy" type="button" @click="toggleSchool(school)">{{ school.is_active ? '停用并切换为只读' : '恢复授权' }}</button></section><section class="school-usage"><p class="eyebrow">基础使用概览</p><div><span><strong>{{ school.student_count }}</strong><small>学生</small></span><span><strong>{{ school.teacher_count }}</strong><small>教师</small></span><span><strong>{{ school.project_count }}</strong><small>项目</small></span></div><p>存储配额 {{ school.storage_quota_mb }} MB</p><p>AI 配额 {{ school.ai_quota }} 次</p></section></div></template><template v-else-if="surface === 'competitions'"><section class="management-list"><article v-for="item in platformStore.state.competitions" :key="item.id"><span class="management-icon"><el-icon><Medal /></el-icon></span><div><small>全平台赛事</small><h2>{{ item.title }}</h2><p>{{ item.description }}</p></div><span>截止 {{ item.registration_deadline?.slice(0, 10) ?? '未设置' }}</span><StatusTag :status="item.status === 'published' ? 'published' : 'draft'" /><button class="secondary-button" :disabled="busy" type="button" @click="askConfirm({ title: item.status === 'published' ? '撤回这项赛事？' : '发布这项赛事？', description: item.status === 'published' ? '撤回后学生和教师将不再看到该赛事。' : '发布后赛事会立即显示在师生端。', confirmText: item.status === 'published' ? '确认撤回' : '确认发布', danger: item.status === 'published', work: () => platformStore.toggleCompetition(item), success: item.status === 'published' ? 'competition_withdrawn' : 'competition_published' })">{{ item.status === 'published' ? '撤回' : '发布' }}</button></article><EmptyState v-if="!platformStore.state.competitions.length" title="暂无赛事" /></section></template><template v-else-if="surface === 'announcements'"><div class="announcement-list"><article v-for="item in platformStore.state.announcements" :key="item.id" class="announcement-card"><div><span>系统公告</span><small>{{ item.published_at?.slice(0, 10) }}</small></div><h2>{{ item.title }}</h2><p>{{ item.body }}</p></article><EmptyState v-if="!platformStore.state.announcements.length" title="暂无系统公告" /></div></template><template v-else-if="surface === 'cases'"><EmptyState title="暂无可治理案例" description="教师发布的公开案例会通过真实案例接口进入这里。" /></template><template v-else-if="surface === 'settings'"><div class="settings-grid"><section class="settings-card"><el-icon><Setting /></el-icon><div><h2>平台安全策略</h2><p>学校数据强制隔离，平台账号不能进入学校项目过程。</p></div><StatusTag status="active" /></section><section class="settings-card"><el-icon><Key /></el-icon><div><h2>服务配置</h2><p>AI 密钥、数据库密码与站点配置仅保存在服务器环境变量。</p></div><StatusTag status="active" /></section></div></template><el-dialog v-model="schoolOpen" title="创建学校空间" width="540px"><form class="dialog-form" @submit.prevent="addSchool"><label>学校名称<input v-model="schoolForm.name"></label><label>授权到期日<input v-model="schoolForm.license_expires_at" type="date"></label><div class="dialog-actions"><button class="secondary-button" type="button" @click="schoolOpen = false">取消</button><button class="primary-button" :disabled="busy" type="submit">创建学校</button></div></form></el-dialog><el-dialog v-model="competitionOpen" title="创建赛事" width="620px"><form class="dialog-form" @submit.prevent="addCompetition"><label>赛事名称<input v-model="competitionForm.title"></label><label>截止日期<input v-model="competitionForm.registration_deadline" type="date"></label><label>赛事说明<textarea v-model="competitionForm.description" rows="4" /></label><div class="dialog-actions"><button class="secondary-button" type="button" @click="competitionOpen = false">取消</button><button class="primary-button" :disabled="busy" type="submit">保存草稿</button></div></form></el-dialog><el-dialog v-model="announcementOpen" title="发布系统公告" width="580px"><form class="dialog-form" @submit.prevent="addAnnouncement"><label>公告标题<input v-model="announcementForm.title"></label><label>公告正文<textarea v-model="announcementForm.body" rows="6" /></label><div class="dialog-actions"><button class="secondary-button" type="button" @click="announcementOpen = false">取消</button><button class="primary-button" :disabled="busy" type="submit">发布公告</button></div></form></el-dialog><ConfirmDialog v-if="confirmState" :model-value="true" :title="confirmState.title" :description="confirmState.description" :confirm-text="confirmState.confirmText" :danger="confirmState.danger" @update:model-value="confirmState = null" @confirm="confirmAction" /></div></template>
